package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService.Decision;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import tools.jackson.databind.node.ObjectNode;

/** Real native entity rows and permanent decision receipt, without claiming a full dedup business action. */
class EntityHeatDecisionJdbcLogTest {
    GenerationJdbcStoreTest f;JdbcEntityHeatSnapshots snapshots;EntityDecisionJdbcLog log;final String hash="a".repeat(64);int actions;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){f=fixture();f.fixture();boolean h2=f.source instanceof org.h2.jdbcx.JdbcDataSource;f.jdbc.execute("DROP TABLE IF EXISTS analyzed_entities");f.jdbc.execute("CREATE TABLE analyzed_entities(id VARCHAR(64) PRIMARY KEY,category VARCHAR(32),revision BIGINT,occurrence_count BIGINT,title VARCHAR(512),summary "+(h2?"CLOB":"MEDIUMTEXT")+",first_recorded_at "+(h2?"TIMESTAMP(6)":"DATETIME(6)")+",first_seen_business_date DATE,legacy_flag INT)");snapshots=new JdbcEntityHeatSnapshots(f.source);log=new EntityDecisionJdbcLog(new JdbcEntityDecisions(f.source),"fictional-owner",f.clock,snapshots);entity("fictional-old",2);entity("fictional-new",1);}
    void entity(String id,long count){f.jdbc.update("INSERT INTO analyzed_entities VALUES(?,'news_tech',3,?,?,'Fictional summary',?,'2026-01-01',0)",id,count,"Fictional "+id,LocalDateTime.ofInstant(Instant.parse("2026-01-01T08:00:00Z"),ZoneOffset.UTC));}
    <T>T write(java.util.function.Supplier<T> work){return f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-heat-outer-"+actions++,"fictional-owner",null),k->null,c->work.get());}
    String payload(){return f.jdbc.queryForObject("SELECT action_payload FROM jobs WHERE target_type='entity_decision'",String.class);}
    void save(Decision result,String operation,String old,String next){log.append("fictional-key",hash,result,operation,result.itemId(),old,next,"Fictional heat native decision");}
    @Test void ActualNativeTouchedStateAndCanonicalV2ReceiptReplayWithoutCurrentRows(){var result=new Decision("fictional-item","fictional-new","ready",true,7L);write(()->{f.jdbc.update("UPDATE analyzed_entities SET occurrence_count=7,revision=4 WHERE id='fictional-new'");save(result,"new",null,"fictional-new");return true;});var n=CanonicalJson.parse(payload());assertEquals("entity-decision-v2",n.get("schema_version").asText());assertEquals(1,n.get("entity_heat_snapshots").size());var original=EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(n.get("entity_heat_snapshots").get(0)));assertEquals(7,original.occurrenceCount());assertEquals(4,original.revision());assertEquals(Instant.parse("2026-01-01T08:00:00Z"),original.firstRecordedAt());assertEquals(result,log.committed("fictional-key",hash));String raw=payload();f.jdbc.execute("DROP TABLE analyzed_entities");assertEquals(result,new EntityDecisionJdbcLog(new JdbcEntityDecisions(f.source),"fictional-owner",f.clock,snapshots).committed("fictional-key",hash));assertEquals(raw,payload());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
    @Test void RealNativeSplitCapturesBothCountsAndExcludeKeepsTheOldSide(){var result=new Decision("fictional-item","fictional-new","ready",true,1L);write(()->{save(result,"split","fictional-old","fictional-new");return true;});var snapshots=CanonicalJson.parse(payload()).get("entity_heat_snapshots");assertEquals(2,snapshots.size());assertEquals(1,EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(snapshots.get(0))).occurrenceCount());assertEquals(2,EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(snapshots.get(1))).occurrenceCount());assertEquals(result,log.committed("fictional-key",hash));f.jdbc.update("DELETE FROM jobs");var excluded=new Decision("fictional-item","fictional-old","excluded",false,0L);write(()->{f.jdbc.update("UPDATE analyzed_entities SET occurrence_count=0,first_seen_business_date=NULL WHERE id='fictional-old'");save(excluded,"exclude","fictional-old",null);return true;});var old=EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(CanonicalJson.parse(payload()).get("entity_heat_snapshots").get(0)));assertEquals(0,old.occurrenceCount());assertNull(old.firstSeenBusinessDate());assertEquals(excluded,log.committed("fictional-key",hash));}
    @Test void MissingOrConflictingNativeEntityAndWholeWriterFailureCannotLeaveAReceipt(){var result=new Decision("fictional-item","fictional-new","ready",true,9L);assertThrows(RuntimeException.class,()->write(()->{save(result,"new",null,"fictional-new");return true;}));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));f.jdbc.update("DELETE FROM analyzed_entities WHERE id='fictional-new'");assertThrows(RuntimeException.class,()->write(()->{save(result,"new",null,"fictional-new");return true;}));entity("fictional-new",1);var valid=new Decision("fictional-item","fictional-new","ready",true,1L);assertThrows(RuntimeException.class,()->write(()->{save(valid,"new",null,"fictional-new");throw new IllegalStateException("Fictional later action failure");}));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
    @Test void NeedsReviewRecordsNoEntityAndLegacyNullFactsAreNotRepaired(){var review=new Decision("fictional-item",null,"needs_review",false,null);write(()->{save(review,"needs_review",null,null);return true;});assertEquals(0,CanonicalJson.parse(payload()).get("entity_heat_snapshots").size());assertEquals(review,log.committed("fictional-key",hash));f.jdbc.update("UPDATE analyzed_entities SET occurrence_count=NULL,legacy_flag=1,first_recorded_at=NULL,first_seen_business_date=NULL,title=NULL,summary=NULL WHERE id='fictional-old'");var unknown=write(()->snapshots.readTouched("fictional-old",null)).getFirst();assertNull(unknown.occurrenceCount());assertTrue(unknown.legacy());assertNull(unknown.firstRecordedAt());}
    @Test void NativeBudgetAndExplicitWriterRcRejectBeforeProducingFacts(){assertThrows(RuntimeException.class,()->snapshots.readTouched(null,null));var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->tx.execute(s->snapshots.readTouched("fictional-old",null)));var writer=new TransactionTemplate(new DataSourceTransactionManager(f.source));writer.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->writer.execute(s->snapshots.readTouched("fictional-old",null)));f.jdbc.update("UPDATE analyzed_entities SET summary=? WHERE id='fictional-old'","F".repeat(65537));assertThrows(RuntimeException.class,()->write(()->snapshots.readTouched("fictional-old",null)));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
    @Test void RehashedV2CountCannotDisagreeWithTheOriginalDecision(){var result=new Decision("fictional-item","fictional-new","ready",true,1L);write(()->{save(result,"new",null,"fictional-new");return true;});var n=(ObjectNode)CanonicalJson.parse(payload());((ObjectNode)n.get("entity_heat_snapshots").get(0)).put("occurrence_count",8);String raw=JdbcFrozenInputs.canonical(n);f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE target_type='entity_decision'",raw,JdbcGenerationLineage.hash(raw));assertThrows(RuntimeException.class,()->log.committed("fictional-key",hash));}
    @Test void ColdNativePortAndV2LogRequireActualDependencyWithoutIo(){var source=mock(javax.sql.DataSource.class);var port=new JdbcEntityHeatSnapshots(source);var store=mock(JdbcEntityDecisions.class);var clock=mock(Clock.class);new EntityDecisionJdbcLog(store,"fictional-owner",clock,port);verifyNoInteractions(source,store,clock);assertThrows(NullPointerException.class,()->new EntityDecisionJdbcLog(store,"fictional-owner",clock,null));}
}
